 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            minr, maxr = min(y for y, x in cells), max(y for y, x in cells)
            minc, maxc = min(x for y, x in cells), max(x for y, x in cells)
            # An enclosed zero (a hole) means the frame-shaped object rises;
            # open/branched objects fall.
            zeros = {(y, x) for y in range(minr, maxr + 1) for x in range(minc, maxc + 1)
                     if (y, x) not in set(cells)}
            exterior = set()
            todo = [(y, x) for y, x in zeros
                    if y in (minr, maxr) or x in (minc, maxc)]
            exterior.update(todo)
            while todo:
                y, x = todo.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if p in zeros and p not in exterior:
                        exterior.add(p)
                        todo.append(p)
            goes_up = bool(zeros - exterior)
            objects.append((color, cells, goes_up))

    out = [[0] * w for _ in range(h)]
    # Pack from the destination edge inward, leaving no overlaps.
    for goes_up in (True, False):
        group = [obj for obj in objects if obj[2] == goes_up]
        group.sort(key=lambda obj: min(y for y, x in obj[1]) if goes_up
                   else -max(y for y, x in obj[1]))
        for color, cells, _ in group:
            current = list(cells)
            dy = -1 if goes_up else 1
            while True:
                nxt = [(y + dy, x) for y, x in current]
                if min(y for y, x in nxt) < 0 or max(y for y, x in nxt) >= h:
                    break
                if any(out[y][x] != 0 for y, x in nxt):
                    break
                current = nxt
            for y, x in current:
                out[y][x] = color
    return out
